// ENG-1947: live proof that the Discourse Context drag payload honours the vault link format.
import { resolveWebSocket } from "/Users/trang.doan/.claude/skills/dg-obsidian-cdp-verify/scripts/websocket.mjs";

const ROOT = "/Users/trang.doan/Documents/testVault";
const PLUGIN = "@discourse-graph/obsidian";

const open = async (url) => {
  const WebSocket = await resolveWebSocket();
  const ws = new WebSocket(url);
  let id = 0;
  const pending = new Map();
  await new Promise((res, rej) => {
    ws.addEventListener("open", res, { once: true });
    ws.addEventListener("error", (e) => rej(e.error ?? new Error("ws")), { once: true });
  });
  ws.addEventListener("message", (ev) => {
    const m = JSON.parse(ev.data.toString());
    const p = m.id && pending.get(m.id);
    if (!p) return;
    pending.delete(m.id);
    m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result);
  });
  const send = (method, params = {}) =>
    new Promise((resolve, reject) => {
      const i = ++id;
      pending.set(i, { resolve, reject });
      ws.send(JSON.stringify({ id: i, method, params }));
    });
  return {
    close: () => ws.close(),
    evaluate: async (expr) => {
      const r = await send("Runtime.evaluate", {
        expression: `(async () => { ${expr} })()`,
        awaitPromise: true,
        returnByValue: true,
      });
      if (r.exceptionDetails)
        throw new Error(r.exceptionDetails.exception?.description ?? "eval failed");
      return r.result.value;
    },
  };
};

const targets = (await (await fetch("http://127.0.0.1:9222/json/list")).json()).filter(
  (t) => t.type === "page" && !t.url.startsWith("devtools://"),
);
let client = null;
for (const t of targets) {
  const c = await open(t.webSocketDebuggerUrl);
  const ok = await c
    .evaluate(`return typeof app !== "undefined" && app.vault?.adapter?.basePath === ${JSON.stringify(ROOT)};`)
    .catch(() => false);
  if (ok === true) { client = c; console.log("attached:", t.title); break; }
  c.close();
}
if (!client) throw new Error("no testVault target");

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Open a node that actually has relations, then show the Discourse Context view.
const setup = await client.evaluate(`
  const raw = await app.vault.adapter.read(".obsidian/plugins/discourse-graphs/relations.json");
  const rels = JSON.parse(raw).relations || [];
  const plugin = app.plugins.plugins[${JSON.stringify(PLUGIN)}];
  // Find a source node whose relation target still resolves to a file.
  for (const r of rels) {
    const src = app.vault.getMarkdownFiles().find(f => {
      const fm = app.metadataCache.getFileCache(f)?.frontmatter;
      return fm && (fm.nodeInstanceId === r.source || fm.nodeInstanceId === r.destination);
    });
    if (!src) continue;
    const leaf = app.workspace.getLeaf(false);
    await leaf.openFile(src);
    return JSON.stringify({ opened: src.path, relId: r.id });
  }
  return JSON.stringify({ error: "no relation resolved to a file", relCount: rels.length });
`);
console.log("setup:", setup);

await client.evaluate(`return app.commands.executeCommandById(${JSON.stringify(PLUGIN + ":toggle-discourse-context")});`);
await sleep(2500);

const probe = async () =>
  client.evaluate(`
    const leaf = app.workspace.getLeavesOfType("discourse-context")[0];
    if (!leaf) return JSON.stringify({ error: "context view not open" });
    const all = Array.from(leaf.view.containerEl.querySelectorAll("a"));
    return JSON.stringify({
      anchors: all.length,
      draggable: all.filter(a => a.draggable).length,
      texts: all.slice(0, 6).map(a => a.textContent),
    });
  `);
console.log("panel:", await probe());

const dragPayload = async () =>
  JSON.parse(
    await client.evaluate(`
      const leaf = app.workspace.getLeavesOfType("discourse-context")[0];
      const a = Array.from(leaf.view.containerEl.querySelectorAll("a")).find(x => x.draggable);
      if (!a) return JSON.stringify({ error: "no draggable anchor" });
      const dt = new DataTransfer();
      a.dispatchEvent(new DragEvent("dragstart", { bubbles: true, cancelable: true, dataTransfer: dt }));
      return JSON.stringify({
        entry: a.textContent,
        plain: dt.getData("text/plain"),
        uriList: dt.getData("text/uri-list"),
      });
    `),
  );

const original = await client.evaluate(`return app.vault.getConfig("useMarkdownLinks");`);
const results = {};
try {
  for (const [label, flag] of [["wikilink (useMarkdownLinks=false)", false], ["markdown (useMarkdownLinks=true)", true]]) {
    await client.evaluate(`app.vault.setConfig("useMarkdownLinks", ${flag}); return true;`);
    await sleep(300);
    results[label] = await dragPayload();
  }
} finally {
  await client.evaluate(`app.vault.setConfig("useMarkdownLinks", ${original}); return true;`);
}
console.log(JSON.stringify(results, null, 2));
console.log("restored useMarkdownLinks:", await client.evaluate(`return app.vault.getConfig("useMarkdownLinks");`));
client.close();

